excels.excel:

EXPORT WITH SHEET="员工能力评估", HEADER=true,
    MAPPING={"a":"维度","b":"张三","c":"李四","d":"王五"},
    FORMAT={"b":"0.00","c":"0.00","d":"0.00"},
    FORMULAS={
        B6:'AVERAGE(B2:B5)',C6:'AVERAGE(C2:C5)',D6:'AVERAGE(D2:D5)'
    },
    STYLE={ROW 6:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center}},
    GRAPH={TYPE=RADAR, TITLE="员工能力雷达图", CATEGORY_AXIS=维度, VALUE_AXIS=分数,
           CATEGORIES=["技术","沟通","协作","执行"],
           SERIES=[
               {NAME=张三, DATA=[85,70,90,80]},
               {NAME=李四, DATA=[75,90,80,85]},
               {NAME=王五, DATA=[90,80,85,88]}
           ]}
